voice:
Você é um assistente de lista de compras de supermercado.
O usuário vai digitar ou falar itens que deseja comprar, muitas vezes em uma única frase ou lista informal.
Extraia cada item individualmente e retorne em formato JSON:
{
  "items": [
    {
      "name": "Nome capitalizado e limpo do item (Ex: Leite Integral, Cebola)",
      "quantity": 1.0,
      "unit": "un, kg, g, l, pct, cx, etc",
      "category": "Uma destas: Hortifrúti, Laticínios e Frios, Carnes e Aves, Padaria e Confeitaria, Mercearia e Despensa, Bebidas, Limpeza, Higiene Pessoal, Congelados, Grãos, Massas e Farinhas, Temperos e Molhos, Enlatados e Conservas, Doces e Chocolates, Castanhas e Sementes, Peixes e Frutos do Mar, Descartáveis e Embalagens, Utilidades e Casa, Jardinagem, Outros",
      "notes": "Observação se houver (ex: sem lactose, marca específica)"
    }
  ]
}

sheets_template:
function doGet(e) {
  return ContentService.createTextOutput(JSON.stringify({
    status: "online",
    message: "Webhook do Mercado PWA ativo e pronto para receber dados."
  })).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
    var payload = JSON.parse(e.postData.contents);

    if (payload.action === "update_pantry" || payload.action === "sync") {
      // Clear previous rows starting from row 2 (keeping headers)
      var lastRow = sheet.getLastRow();
      if (lastRow > 1) {
        sheet.getRange(2, 1, lastRow - 1, 5).clearContent();
      }

      // Ensure header row exists
      if (lastRow === 0) {
        sheet.appendRow(["Produto", "Categoria", "Quantidade", "Unidade", "Data da Compra"]);
      }

      var rows = [];
      for (var i = 0; i < payload.items.length; i++) {
        var it = payload.items[i];
        rows.push([it.name, it.category, it.quantity, it.unit, it.purchased_at]);
      }

      if (rows.length > 0) {
        sheet.getRange(2, 1, rows.length, 5).setValues(rows);
      }

      return ContentService.createTextOutput(JSON.stringify({
        status: "success",
        updated_items: rows.length,
        timestamp: new Date().toISOString()
      })).setMimeType(ContentService.MimeType.JSON);
    }

    return ContentService.createTextOutput(JSON.stringify({ status: "ignored" })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ status: "error", message: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}
